INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('7aec834d-1fd2-4d7e-bc70-54e666ea30b6', '57n6riwz63gjghwii2umc', 'dice que no pudo interpretar la consulta que le pedi', '["Musly Router","Agente General / QA (01-melosmile-agent-qa)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-08-22T17:22:10.118Z"},{"role":"user","text":"agenda una revision para munir el lunes en goya a las 13:00","timestamp":"2026-08-22T17:22:29.156Z"},{"role":"assistant","text":"No se pudo interpretar la respuesta del asistente. Por favor, reformula tu pregunta.","intent":"general_query","timestamp":"2026-08-22T17:22:35.620Z"}]', '2026-08-22T17:23:07.75+00:00', false, NULL, NULL) ON CONFLICT DO NOTHING;
